"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["45738"],{47759(e){e.exports=JSON.parse('{"id":"FIN-1118","slug":"market-value-added","term":"Market Value Added (MVA)","also_known_as":["MVA"],"difficulty":"Advanced","definition":"Market value added (MVA) is the difference between a company\'s market value and the total capital invested in it by shareholders and lenders, showing how much value management has created or destroyed.","explanation":["MVA compares what investors have put into a company with what the company is now worth in the market. A positive MVA means the company has created value; a negative MVA means it has destroyed value.","It is typically calculated as the market value of equity and debt minus the total capital invested. For example, if investors have put 10 billion into a company over its life, and its debt and equity are now worth 15 billion, its MVA is 5 billion.","MVA is closely linked to economic profit. In theory, a company\'s MVA equals the present value of all the economic profit investors expect it to earn in future. Companies that consistently earn returns above their cost of capital tend to have high MVA.","MVA reflects market expectations, so it changes with share prices and can be affected by market sentiment that has little to do with management\'s performance. Measuring invested capital also requires adjustments to accounting figures, which can vary between analysts."],"note":"","total":1500,"prev":{"slug":"market-value","term":"Market Value"},"next":{"slug":"marketplace-model","term":"Marketplace Model"}}')}}]);